const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const start_date = '2018-01-01';
  const end_date = '2019-12-31';

  // Define San Jose and Los Angeles as points with a buffer to represent the city area.
  const sanJose = ee.Geometry.Point([-121.8863, 37.3382]).buffer(25000); // San Jose center, 25km buffer
  const losAngeles = ee.Geometry.Point([-118.2437, 34.0522]).buffer(25000); // Los Angeles center, 25km buffer

  // Define the S5P NO2 collection and band
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFLINE_L3_NO2')
    .select('NO2_column_number_density', 'qa_value')
    .filterDate(start_date, end_date);

  // Function to mask clouds and low quality data
  const maskClouds = function(image) {
    const qa = image.select('qa_value');
    // Filter out images with qa_value < 0.75 (low quality, clouds)
    // and where NO2 value is non-negative.
    const mask = qa.gte(0.75).and(image.select('NO2_column_number_density').gt(0));
    return image.updateMask(mask);
  };

  const processedCollection = collection.map(maskClouds);

  // 2. Data Acquisition & Check for San Jose
  const sjCollection = processedCollection.filterBounds(sanJose);
  if (sjCollection.size().getInfo() === 0) {
    console.log("C1: No data found for San Jose in the specified period.");
    return;
  }

  // 2. Data Acquisition & Check for Los Angeles
  const laCollection = processedCollection.filterBounds(losAngeles);
  if (laCollection.size().getInfo() === 0) {
    console.log("C1: No data found for Los Angeles in the specified period.");
    return;
  }

  // Take the mean over the time period for each city
  const sjMeanImage = sjCollection.mean();
  const laMeanImage = laCollection.mean();

  const band = 'NO2_column_number_density';
  const scale = 1000; // Use a reasonable scale for reduction

  // 3. Processing & Calculation for San Jose
  const sjReducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const sjStats = await sjMeanImage.reduceRegion({
    reducer: sjReducer,
    geometry: sanJose,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16 // Increase tileScale for larger regions
  }).getInfo();

  const sjAvgNo2 = sjStats[band];
  const sjPixelCount = sjStats[band + '_count'];

  if (sjPixelCount === 0 || sjAvgNo2 === null || sjAvgNo2 === undefined || isNaN(sjAvgNo2)) {
    console.log("C2: No valid pixels or C3: Calculation failure for San Jose after masking.");
    return;
  }

  // 3. Processing & Calculation for Los Angeles
  const laStats = await laMeanImage.reduceRegion({
    reducer: sjReducer, // Re-using the same combined reducer
    geometry: losAngeles,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const laAvgNo2 = laStats[band];
  const laPixelCount = laStats[band + '_count'];

  if (laPixelCount === 0 || laAvgNo2 === null || laAvgNo2 === undefined || isNaN(laAvgNo2)) {
    console.log("C2: No valid pixels or C3: Calculation failure for Los Angeles after masking.");
    return;
  }

  // 4. Validation & Final Answer
  console.log(`San Jose NO2 Avg (mol/m^2): ${sjAvgNo2 ? sjAvgNo2.toExponential(2) : 'N/A'}, Pixels: ${sjPixelCount}`);
  console.log(`Los Angeles NO2 Avg (mol/m^2): ${laAvgNo2 ? laAvgNo2.toExponential(2) : 'N/A'}, Pixels: ${laPixelCount}`);

  if (sjAvgNo2 > laAvgNo2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
